    def depends(
        cls,
        scheduling_state: DagSchedulingState | None = Query(
            None,
            description="Filter Dags by scheduling state: active, draining or paused.",
        ),
    ) -> _SchedulingStateFilter:
        return cls().set_value(scheduling_state)


